import * as THREE from './vendor/three.module.js';
import {WEAPONS,MELEE_WEAPONS} from './weapons.js';
import {loadFieldKit} from './field-kit.js';
import {HEROES,ACCESSORIES,createHeroActor,validateOperative,saveOperative} from './avatars.js';
const $=id=>document.getElementById(id);
export function initHeroMenu(assets,initial,onCommit){
 const listeners=new Set();let search='',saving=false;
 let committed=validateOperative(initial),draft={...committed},actor,renderer,scene,camera,generation=0,angle=.25,mode='idle',needsFit=true,drag=false,lastX=0,heldGroup,heldModel,heldId,companion,nanoGeneration=0;
 function setup(){if(renderer)return;renderer=new THREE.WebGLRenderer({canvas:$('hero-preview'),antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;scene=new THREE.Scene();heldGroup=new THREE.Group();scene.add(heldGroup);scene.add(new THREE.HemisphereLight('#d7f3ff','#334c5b',2.7));const light=new THREE.DirectionalLight('#fff0d8',3);light.position.set(2,4,4);scene.add(light);camera=new THREE.PerspectiveCamera(35,1,.02,20);camera.position.set(0,1.25,4.5);camera.lookAt(0,1.1,0);const floor=new THREE.Mesh(new THREE.CylinderGeometry(.7,.8,.08,48),new THREE.MeshStandardMaterial({color:'#234d61',roughness:.6}));floor.position.y=-.04;scene.add(floor);}
 async function preview(){setup();const token=++generation,hero=HEROES.find(h=>h.id===draft.hero);$('hero-preview-status').textContent='Loading '+hero.name+'...';await assets.ensureRig(hero.asset);if(token!==generation)return;actor?.dispose();actor=createHeroActor(assets,draft);scene.add(actor.root);needsFit=true;$('hero-preview-status').textContent='Drag to rotate / Preview movement below';}
 function render(){const dirty=JSON.stringify(draft)!==JSON.stringify(committed);$('equip-hero').textContent=saving?'APPLYING...':'APPLY OPERATIVE';$('hero-save-state').textContent=saving?'Equipping your operative...':dirty?'Previewing changes. Apply to equip.':'Appearance saves on this device.';$('equip-hero').disabled=!dirty||saving;for(const fn of listeners)fn({dirty});$('hero-count').textContent=`${HEROES.length} heroes / ${ACCESSORIES.length} accessories`;const hero=HEROES.find(h=>h.id===draft.hero);$('hero-detail-name').textContent=hero.name;const list=$('hero-roster');list.replaceChildren();const visible=HEROES.filter(h=>h.name.toLowerCase().includes(search));for(const h of visible){const b=document.createElement('button');b.className='hero-tile'+(h.id===draft.hero?' selected':'');b.setAttribute('aria-pressed',String(h.id===draft.hero));b.dataset.heroId=h.id;b.tabIndex=h.id===draft.hero||!visible.some(x=>x.id===draft.hero)&&h===visible[0]?0:-1;b.title=h.name;b.innerHTML=`<img src="${h.portrait}" alt=""><span>${h.name}</span>`;b.onclick=()=>{draft.hero=h.id;render();$('hero-roster').querySelector(`[data-hero-id="${h.id}"]`)?.focus();preview().catch(fail)};list.appendChild(b)}if(!visible.length){const empty=document.createElement('p');empty.className='empty-collection';empty.textContent='No operatives match. Try another name.';list.append(empty)}for(const slot of ['head','back']){const select=$('hero-'+slot);select.replaceChildren();const none=document.createElement('option');none.value='none';none.textContent='None';select.appendChild(none);for(const a of ACCESSORIES.filter(a=>a.slot===slot)){const option=document.createElement('option');option.value=a.id;option.textContent=a.name;select.appendChild(option)}select.value=draft[slot]}}
 function fail(e){$('hero-preview-status').textContent=e.message}
 function open(){document.querySelector('[data-hub-tab=operative]')?.click();render();preview().catch(fail)}
 function close(){$('hero-preview-status').textContent='Operative applied. Drag to rotate.'}
 $('hero-button').onclick=open;$('close-hero').onclick=close;
 async function apply(){if(saving)return false;if(JSON.stringify(draft)===JSON.stringify(committed))return true;saving=true;render();try{const selection={...draft};await onCommit(selection);committed=selection;saveOperative(committed);$('selected-hero-name').textContent=HEROES.find(h=>h.id===committed.hero).name;close();return true}catch(e){fail(e);return false}finally{saving=false;render()}}
 $('equip-hero').onclick=apply;
 $('hero-search').oninput=e=>{search=e.target.value.toLowerCase().trim();render()};
 $('hero-roster').onkeydown=e=>{const tiles=[...$('hero-roster').querySelectorAll('[data-hero-id]')],index=tiles.indexOf(document.activeElement);if(index<0)return;const columns=typeof getComputedStyle==='function'?Math.max(1,getComputedStyle($('hero-roster')).gridTemplateColumns.split(' ').length):6;const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-columns,ArrowDown:columns}[e.code];let next;if(delta!==undefined)next=Math.max(0,Math.min(tiles.length-1,index+delta));else if(e.code==='Home')next=0;else if(e.code==='End')next=tiles.length-1;else return;e.preventDefault();tiles[next].click()};

 for(const slot of ['head','back'])$('hero-'+slot).onchange=e=>{draft[slot]=e.target.value;render();preview().catch(fail)};
 document.querySelectorAll('[data-avatar-motion]').forEach(b=>b.onclick=()=>{mode=b.dataset.avatarMotion;document.querySelectorAll('[data-avatar-motion]').forEach(el=>el.classList.toggle('selected',el===b))});
 const canvas=$('hero-preview');canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag){angle+=(e.clientX-lastX)*.012;lastX=e.clientX}};canvas.onpointerup=()=>drag=false;
 $('hero-turn-left').onclick=()=>angle-=.5;$('hero-turn-right').onclick=()=>angle+=.5;$('selected-hero-name').textContent=HEROES.find(h=>h.id===committed.hero).name;
 function setWeapon(id){setup();if(heldId===id)return;heldId=id;if(heldModel)heldGroup.remove(heldModel);const cfg=WEAPONS[id]||MELEE_WEAPONS[id];if(!cfg?.asset)return;const bounds=assets.manifest.assets[cfg.asset].bounds;heldModel=assets.model(cfg.asset,cfg.archetype==='melee'?{height:.85}:{scale:.65/Math.max(...bounds.size)});heldGroup.add(heldModel);}
 async function setNano(n){setup();const token=++nanoGeneration;await assets.ensureRig(n.asset);if(token!==nanoGeneration)return;companion?.userData.animation?.dispose();companion?.parent?.remove(companion);companion=assets.model(n.asset,{height:.45});scene.add(companion)}
 render();preview().catch(fail);setWeapon(loadFieldKit().gun);
 return {open,close,setWeapon,setNano,apply,get isDirty(){return JSON.stringify(draft)!==JSON.stringify(committed)},async discard(){draft={...committed};render();await preview().catch(fail)},subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn)},setMotion(value){mode=value;document.querySelectorAll('[data-avatar-motion]').forEach(el=>el.classList.toggle('selected',el.dataset.avatarMotion===mode))},update(dt,time){if($('menu').classList.contains('hidden')||!renderer||!actor)return;const rect=canvas.getBoundingClientRect();if(rect.width<2||rect.height<2)return;if(canvas.width!==Math.round(rect.width*renderer.getPixelRatio())||canvas.height!==Math.round(rect.height*renderer.getPixelRatio())){renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();needsFit=true}actor.root.rotation.y=angle;actor.update(dt,{moving:mode==='run',sprinting:mode==='run',crouch:mode==='crouch'?1:0,slide:mode==='slide'?1:0});actor.root.updateMatrixWorld(true);if(actor.sockets.rightHand)actor.sockets.rightHand.getWorldPosition(heldGroup.position);else heldGroup.position.set(.35,1,.15);heldGroup.quaternion.copy(actor.root.quaternion);if(companion){companion.position.set(.85+Math.sin(time*1.1)*.07,1.13+Math.sin(time*1.8)*.07,.15);companion.rotation.y=angle;companion.userData.animation?.update(dt,'idle')}if(needsFit){actor.root.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(actor.root),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3()),tangent=Math.tan(camera.fov*Math.PI/360),distance=Math.max(size.y/(2*tangent),size.x/(2*tangent*camera.aspect))*1.22;camera.position.set(0,center.y+.12,center.z+distance);camera.lookAt(center);needsFit=false}renderer.render(scene,camera)}};
}
